dashboard.definition:
{
	"title": "SAP LogServ - Linux System & Security",
	"description": "",
	"inputs": {
		"input_global_trp": {
			"options": {"defaultValue": "-30d@d,now", "token": "global_time"},
			"title": "Global Time Range",
			"type": "input.timerange"
		},
		"input_nav_dropdown": {
			"type": "input.dropdown",
			"title": "Navigate to Dashboard",
			"options": {
				"items": [
					{"label": "Overview", "value": "logserv_overview"},
					{"label": "DNS Analytics", "value": "logserv_dns_analytics"},
					{"label": "HANA Audit", "value": "logserv_hana_audit"},
					{"label": "HANA Trace", "value": "logserv_hana_trace"},
					{"label": "Web Dispatcher", "value": "logserv_web_dispatcher"},
					{"label": "Host Details", "value": "logserv_host_details"},
					{"label": "ABAP Security", "value": "logserv_abap_security"},
					{"label": "ABAP Operations", "value": "logserv_abap_operations"},
					{"label": "SAP Services", "value": "logserv_sap_services"},
					{"label": "Cloud Connector", "value": "logserv_cloud_connector"},
					{"label": "Windows", "value": "logserv_windows"},
					{"label": "Proxy", "value": "logserv_proxy"},
					{"label": "Environment Health", "value": "logserv_environment_health"}
				],
				"token": "nav_target"
			}
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$"
					}
				}
			}
		}
	},
	"visualizations": {
		"viz_kpi_total": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_total"},
			"title": "Total Events",
			"options": {"majorValue": "> primary | seriesByName('total') | lastPoint()", "backgroundColor": "transparent", "sparklineDisplay": "off", "trendDisplay": "off"}
		},
		"viz_kpi_fw_drops": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_fw_drops"},
			"title": "Firewall Drops",
			"options": {"majorValue": "> primary | seriesByName('drops') | lastPoint()", "majorColor": "#dc4e41", "backgroundColor": "transparent", "sparklineDisplay": "off", "trendDisplay": "off"}
		},
		"viz_kpi_hosts": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_hosts"},
			"title": "Active Hosts",
			"options": {"majorValue": "> primary | seriesByName('hosts') | lastPoint()", "backgroundColor": "transparent", "sparklineDisplay": "off", "trendDisplay": "off"}
		},
		"viz_volume_by_type": {
			"type": "splunk.line",
			"dataSources": {"primary": "ds_volume_by_type"},
			"title": "Event Volume by Sourcetype",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {"backgroundColor": "transparent", "xAxisTitleVisibility": "hide", "yAxisTitleVisibility": "hide"}
		},
		"viz_sap_app_activity": {
			"type": "splunk.column",
			"dataSources": {"primary": "ds_sap_app_activity"},
			"title": "SAP Application Activity",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {"backgroundColor": "transparent", "stackMode": "stacked", "xAxisTitleVisibility": "hide", "yAxisTitleVisibility": "hide"}
		},
		"viz_sap_instances": {
			"type": "splunk.table",
			"dataSources": {"primary": "ds_sap_instances"},
			"title": "SAP Instance Distribution",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			}
		},
		"viz_fw_timeline": {
			"type": "splunk.column",
			"dataSources": {"primary": "ds_fw_timeline"},
			"title": "Firewall Drops Over Time",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"xAxisTitleVisibility": "hide", "yAxisTitleVisibility": "hide",
				"seriesColors": ["#dc4e41"]
			}
		},
		"viz_fw_top_sources": {
			"type": "splunk.table",
			"dataSources": {"primary": "ds_fw_top_sources"},
			"title": "Top Blocked Sources",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			}
		},
		"viz_fw_top_ports": {
			"type": "splunk.table",
			"dataSources": {"primary": "ds_fw_top_ports"},
			"title": "Top Blocked Destination Ports",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			}
		},
		"viz_kernel_events": {
			"type": "splunk.pie",
			"dataSources": {"primary": "ds_kernel_events"},
			"title": "Kernel Event Types",
			"showProgressBar": false, "showLastUpdated": false,
			"options": {"showDonutHole": true, "backgroundColor": "transparent"}
		},
		"viz_rect_r1l": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r1r": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r2l": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r2m": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r2r": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r3l": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_rect_r3r": {"type": "splunk.rectangle", "options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}},
		"viz_nav_go": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_nav_go"},
			"options": {
				"majorValue": "> primary | seriesByName('label') | lastPoint()",
				"backgroundColor": "#0877a6", "majorColor": "#ffffff",
				"sparklineDisplay": "off", "trendDisplay": "off", "majorFontSize": 14
			},
			"eventHandlers": [{"type": "drilldown.customUrl", "options": {"url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$", "newTab": false}}]
		}
	},
	"dataSources": {
		"ds_kpi_total": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype IN (\"linux_messages_syslog\", \"syslog\", \"linux_secure\") | stats count as total"}
		},
		"ds_kpi_fw_drops": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"linux_secure\" | rex field=_raw \"(?<fw_action>IN_DROP|IN_ACCEPT)\" | where fw_action=\"IN_DROP\" | stats count as drops"}
		},
		"ds_kpi_hosts": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype IN (\"linux_messages_syslog\", \"syslog\", \"linux_secure\") | stats dc(host) as hosts"}
		},
		"ds_volume_by_type": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype IN (\"linux_messages_syslog\", \"syslog\", \"linux_secure\") | timechart span=1d count by sourcetype"}
		},
		"ds_sap_app_activity": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"linux_messages_syslog\" sap_app=* | stats count by sap_app sap_sid | sort -count | head 20"}
		},
		"ds_sap_instances": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"linux_messages_syslog\" sap_sid=* | stats count as Events dc(host) as Hosts by sap_sid sap_inst sap_cid | sort -Events | head 20 | rename sap_sid as SID sap_inst as Instance sap_cid as CID"}
		},
		"ds_fw_timeline": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"linux_secure\" | timechart span=1d count as \"Firewall Events\""}
		},
		"ds_fw_top_sources": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"linux_secure\" | rex field=_raw \"SRC=(?<fw_src>[^ ]+)\" | rex field=_raw \"DST=(?<fw_dst>[^ ]+)\" | rex field=_raw \"PROTO=(?<fw_proto>[^ ]+)\" | where isnotnull(fw_src) | stats count as \"Drops\" dc(fw_dst) as \"Targets\" values(fw_proto) as Protocol by fw_src | sort -Drops | head 20 | rename fw_src as \"Source IP\""}
		},
		"ds_fw_top_ports": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"linux_secure\" | rex field=_raw \"DPT=(?<fw_dpt>[^ ]+)\" | rex field=_raw \"PROTO=(?<fw_proto>[^ ]+)\" | where isnotnull(fw_dpt) | stats count as \"Drops\" dc(host) as Hosts by fw_dpt fw_proto | sort -Drops | head 20 | rename fw_dpt as \"Dest Port\" fw_proto as Protocol"}
		},
		"ds_kernel_events": {
			"type": "ds.search",
			"options": {"query": "`sap_logserv_idx_macro` sourcetype=\"linux_secure\" | rex field=_raw \"kernel:.*?\\]\\s+(?<kernel_event>[A-Z_]+)\" | where isnotnull(kernel_event) | stats count by kernel_event | sort -count | head 10"}
		},
		"ds_nav_go": {
			"type": "ds.search",
			"options": {"query": "| makeresults | eval label=\"Go >\"", "queryParameters": {"earliest": "-1m", "latest": "now"}}
		}
	},
	"layout": {
		"globalInputs": ["input_global_trp", "input_nav_dropdown"],
		"layoutDefinitions": {
			"layout_1": {
				"options": {"height": 1200, "width": 1920},
				"structure": [
					{"item": "viz_nav_go", "type": "block", "position": {"x": 1790, "y": 0, "w": 120, "h": 35}},
					{"item": "viz_kpi_total", "type": "block", "position": {"x": 10, "y": 45, "w": 300, "h": 90}},
					{"item": "viz_kpi_fw_drops", "type": "block", "position": {"x": 320, "y": 45, "w": 300, "h": 90}},
					{"item": "viz_kpi_hosts", "type": "block", "position": {"x": 630, "y": 45, "w": 300, "h": 90}},
					{"item": "viz_rect_r1l", "type": "block", "position": {"x": 10, "y": 150, "w": 940, "h": 340}},
					{"item": "viz_volume_by_type", "type": "block", "position": {"x": 20, "y": 155, "w": 920, "h": 330}},
					{"item": "viz_rect_r1r", "type": "block", "position": {"x": 960, "y": 150, "w": 950, "h": 340}},
					{"item": "viz_sap_app_activity", "type": "block", "position": {"x": 970, "y": 155, "w": 930, "h": 330}},
					{"item": "viz_rect_r2l", "type": "block", "position": {"x": 10, "y": 505, "w": 620, "h": 340}},
					{"item": "viz_sap_instances", "type": "block", "position": {"x": 20, "y": 510, "w": 600, "h": 330}},
					{"item": "viz_rect_r2m", "type": "block", "position": {"x": 640, "y": 505, "w": 640, "h": 340}},
					{"item": "viz_fw_timeline", "type": "block", "position": {"x": 650, "y": 510, "w": 620, "h": 330}},
					{"item": "viz_rect_r2r", "type": "block", "position": {"x": 1290, "y": 505, "w": 620, "h": 340}},
					{"item": "viz_kernel_events", "type": "block", "position": {"x": 1300, "y": 510, "w": 600, "h": 330}},
					{"item": "viz_rect_r3l", "type": "block", "position": {"x": 10, "y": 860, "w": 950, "h": 330}},
					{"item": "viz_fw_top_sources", "type": "block", "position": {"x": 20, "y": 865, "w": 930, "h": 320}},
					{"item": "viz_rect_r3r", "type": "block", "position": {"x": 970, "y": 860, "w": 940, "h": 330}},
					{"item": "viz_fw_top_ports", "type": "block", "position": {"x": 980, "y": 865, "w": 920, "h": 320}}
				],
				"type": "absolute"
			}
		},
		"options": {},
		"tabs": {"items": [{"label": "New tab", "layoutId": "layout_1"}]}
	}
}
